```python
import http.server
import socket
import logging

class PhishingSimulatorServer:
    def __init__(self):
        self.host = '0.0.0.0'
        self.port = 8080
        self.logger = logging.getLogger('PhishingSimulatorServer')

    def handle_request(self, request):
        data = request.recv(1024).decode()
        self.logger.info(f"Received request from {request.remote_address[0]}:{request.remote_address[1]}")

        # Process the request
        if request.path == '/login':
            # Redirect after a delay
            response = '200 OK'
            response += '\n'
            response += 'Content-Type: text/html\r\n\r\n'
            response += '<!DOCTYPE html>'
            response += '<html><body><h1>Phishing Simulation</h1></body></html>'
            return response
        else:
            # Return a 404 error for all other requests
            return "404 Not Found"

    def run(self):
        try:
            server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            server_socket.bind((self.host, self.port))
            server_socket.listen()
            self.logger.info(f"Listening on {self.host}:{self.port}")

            while True:
                client_socket, addr = server_socket.accept()
                self.logger.info(f"Connected by {addr}")
                self.handle_request(client_socket)
        except Exception as e:
            self.logger.error(f"Error: {str(e)}")
            raise

if __name__ == "__main__":
    phisher = PhishingSimulatorServer()
    phisher.run()
```

