                function updateTimer() {
                    seconds += 1;
                    if (seconds === 60) {
                        minutes += 1;
                        seconds = 0;
                        document.getElementById('timer').textContent = `Time Elapsed: ${minutes}:${seconds.toString().padStart(2, '0')}`;
                    } else {
                        document.getElementById('timer').textContent = `Time Elapsed: ${minutes}:${seconds.toString().padStart(2, '0')}`;
                    }
                }
                updateTimer();
                if (seconds === 59) {
                    clearInterval(timer);
                    document.getElementById('timer').textContent = 'Time Elapsed: 00:00';
                }
            }, 1000);
        }

        window.onload = startTimer;
    </script>
